#!/usr/bin/env node

/**
 * Generates Markdown route lists per provider.
 *
 * Usage:
 *   node scripts/generate-readme-routes.js
 *   node scripts/generate-readme-routes.js --write
 *   node scripts/generate-readme-routes.js --check
 *
 * By default, output is written to stdout. Use --write to update README.md or
 * --check to verify that README.md is up to date.
 */

import { glob, readFile, readdir, writeFile } from "node:fs/promises";
import { basename } from "node:path";

const cacheDir = "cache";
const readmePath = "README.md";
const generatedMarker =
  "<!-- generated by scripts/generate-readme-routes.js -->";
const httpMethods = new Set([
  "delete",
  "get",
  "head",
  "options",
  "patch",
  "post",
  "put",
  "trace",
]);

async function generateReadmeRoutes() {
  const lines = [];
  const providers = (await readdir(cacheDir, { withFileTypes: true }))
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort();

  for (const provider of providers) {
    const routes = [];

    for await (const filePath of glob(
      `${cacheDir}/${provider}/routes/**/*.json`,
    )) {
      const relativePath = filePath.replace(
        `${cacheDir}/${provider}/routes/`,
        "",
      );

      const parts = relativePath.split("/");
      const methodFile = parts.pop();
      const method = basename(methodFile, ".json");
      if (!httpMethods.has(method)) continue;

      const routePath =
        "/" +
        parts.join("/").replaceAll("_QMARK_", "?").replaceAll("_EQ_", "=");
      const encodedRelativePath = relativePath
        .split("/")
        .map((segment) => encodeURIComponent(segment))
        .join("/");
      const specUrl = `https://github.com/gr2m/ai-provider-monitor/blob/main/cache/${encodeURIComponent(provider)}/routes/${encodedRelativePath}`;
      routes.push({ method: method.toUpperCase(), routePath, specUrl });
    }

    routes.sort((a, b) => {
      const pathComparison = a.routePath.localeCompare(b.routePath);
      if (pathComparison !== 0) return pathComparison;
      return a.method.localeCompare(b.method);
    });

    if (routes.length === 0) continue;

    lines.push(
      `### ${provider}`,
      "",
      `Event type: \`ai-provider-monitor:${provider}\``,
      "",
    );
    for (const { method, routePath, specUrl } of routes) {
      lines.push(`- [\`${method} ${routePath}\`](${specUrl})`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

async function getExpectedReadme(generatedRoutes) {
  const readme = await readFile(readmePath, "utf8");
  const markerIndex = readme.indexOf(generatedMarker);
  if (markerIndex === -1) {
    throw new Error(`Missing generated routes marker in ${readmePath}`);
  }

  const markerEnd = markerIndex + generatedMarker.length;
  return `${readme.slice(0, markerEnd)}\n\n${generatedRoutes}`;
}

const generatedRoutes = await generateReadmeRoutes();
const command = process.argv[2];

if (command === "--write") {
  await writeFile(readmePath, await getExpectedReadme(generatedRoutes));
} else if (command === "--check") {
  const [readme, expectedReadme] = await Promise.all([
    readFile(readmePath, "utf8"),
    getExpectedReadme(generatedRoutes),
  ]);
  if (readme !== expectedReadme) {
    console.error(
      `${readmePath} is out of date. Run node scripts/generate-readme-routes.js --write.`,
    );
    process.exitCode = 1;
  }
} else if (command) {
  console.error(`Unknown option: ${command}`);
  process.exitCode = 1;
} else {
  process.stdout.write(generatedRoutes);
}
